; ----------------------------------------------------------------------
; THE BANK OF THE BOSSES AND OF COLLISIONS WITH THE MAP
; This bank holds the mover routines of the stage bosses, the routine that
; says whether a point collides with the map, and a good part of the
; drawing. It starts in an odd way: the first instruction is NOT entirely
; here; its first two bytes are the last ones of bank 1.
; ----------------------------------------------------------------------
continued_from_bank_1:		; This is where the split instruction that starts at p01:7FFE continues.
	add hl,bc			;8001   ; HL arrives here from bank 1
	ld a,(hl)			;8002
	exx			;8003
	ld c,a			;8004   ; The byte is kept in the alternate C
	exx			;8005
	ld de,0e790h		;8006   ; 0xE790 and 0xE7C0: if the boss is already set up, it is not set up again
	ld a,(de)			;8009
	and a			;800a
	jr z,L_8013		;800b
	ld de,0e7c0h		;800d
	ld a,(de)			;8010
	and a			;8011
	ret nz			;8012
L_8013:
	ld hl,08051h		;8013   ; Ten bytes from 0x8051 to the card
	ld bc,0000ah		;8016
	ldir		;8019
	ld a,006h		;801b
	call 04062h		;801d
	exx			;8020
	bit 0,c		;8021   ; Bit 0 of C: the first piece
	exx			;8023
	push de			;8024
	call nz,L_8038		;8025
	pop de			;8028
	ld a,010h		;8029
	call 04062h		;802b
	exx			;802e
	bit 1,c		;802f   ; And bit 1: the second
	exx			;8031
	ret z			;8032
	ld hl,08067h		;8033
	jr L_803B		;8036
L_8038:
	ld hl,0805bh		;8038
L_803B:
	ld bc,0000ch		;803b   ; Twelve bytes of card
	ldir		;803e
	ret			;8040

