L_8079:
	push bc			;8079
	ld a,(ix+000h)		;807a
	cp 004h		;807d   ; Type 4
	call z,fire_piece_shot		;807f
	pop bc			;8082
	ld de,00010h		;8083   ; Sixteen bytes: the next slot
	add ix,de		;8086
	djnz L_8079		;8088
