run_six_pieces:		; The six slots at 0xE790: each with its mover routine according to its type
	ld ix,0e790h		;8100
	ld b,006h		;8104   ; Six slots
L_8106:
	push bc			;8106
	call piece_step		;8107
	pop bc			;810a
	ld de,00010h		;810b   ; Sixteen bytes: the next slot
	add ix,de		;810e
	djnz L_8106		;8110
