	jr z,withdraw_piece		;8119   ; Type 3 withdraws
	dec (ix+008h)		;811b
	ret nz			;811e
	ld a,r		;811f   ; The R register: five to eight frames per step
	and 003h		;8121
	add a,005h		;8123
	ld (ix+008h),a		;8125
	ld c,001h		;8128
