	ld b,038h		;8197
L_8199:
	ld a,0f8h		;8199   ; Or eight to the left
	add a,c			;819b   ; Byte 16: how far it gets
	cp b			;819c   ; With a limit
	ret c			;819d
	ld (ix+003h),a		;819e
	ret			;81a1
switch_off_piece:		; The slot and its two marks, zeroed
