aim_both_turrets:		; The two pieces at 0xE790 and 0xE7C0 look towards the ship: the angle chooses the turret's drawing
	ld ix,0e790h		;81d5
	call aim_one_turret		;81d9
	ld ix,0e7c0h		;81dc
aim_one_turret:		; Measures where the ship is and, with the angle, takes from the table the drawing due to each turret
	ld a,(ix+000h)		;81e0
	and a			;81e3
	ret z			;81e4
	ld e,(ix+003h)		;81e5   ; The position of the piece
	ld d,(ix+005h)		;81e8
	call 066d5h		;81eb   ; Bank 1 measures the angle to the ship
	call aim_the_other		;81ee
	ld a,(ix+020h)		;81f1   ; Byte 32: the second turret
	and a			;81f4
	ret z			;81f5
