	jr z,L_8209		;81fa
	ld hl,08250h		;81fc   ; The table at 0x8250
	call angle_drawing		;81ff   ; The turret's drawing
	ld (ix+02bh),c		;8202   ; The drawing is stored
	call is_in_angle		;8205
	ret nc			;8208
L_8209:
	ld (ix+02bh),01dh		;8209
	ret			;820d
aim_the_other:		; The same for the turret of byte 16, with the table at 0x8270
	ld a,(ix+010h)		;820e
	and a			;8211
	ret z			;8212
	bit 6,(ix+00ah)		;8213
	jr nz,L_8226		;8217
	ld hl,08270h		;8219   ; The table at 0x8270
	call angle_drawing		;821c
	ld (ix+01bh),c		;821f
	call is_in_angle		;8222
	ret nc			;8225
L_8226:
	ld (ix+01bh),00ah		;8226
	ret			;822a
is_in_angle:		; Above Y 0x40, and with the drawing between 0x0A and 0x1E, the turret can aim
	ld a,(ix+005h)		;822b
	cp 040h		;822e   ; Above Y 0x40, no
	ret nc			;8230
	ld a,c			;8231
	sub 00ah		;8232   ; And the drawing has to fall between 0x0A and 0x1E
	cp 014h		;8234
	ccf			;8236
	ret			;8237
angle_drawing:		; The angle at 0xEC18 divided by eight indexes the table, and the R register adds a nudge of minus one to one
