; ----------------------------------------------------------------------
; THE ACCELERATION TOWARDS THE SHIP COMES FROM A TABLE OF 256 WORDS
; For an object to curve towards the ship it needs a vertical and a
; horizontal acceleration, and here they are not calculated: they are looked
; up. The two differences are taken in absolute value, the high nibble of
; one is joined with the high nibble of the other in a single byte, and that
; byte (times two) indexes the table at 0x9657, which is 256 words. It is
; read twice, crossing the nibbles, and that gives the two components; the
; sign is set by the two's complement.
; ----------------------------------------------------------------------
aim_acceleration:		; The two differences to the ship, in absolute value, give the index into the table at 0x9657: the two accelerations come from there
	ld b,000h		;95eb
	ld a,(0e206h)		;95ed   ; 0xE206: the ship's column
	ld d,a			;95f0
	ld a,(ix+006h)		;95f1
	sub d			;95f4
	jr nc,L_95FA		;95f5
	neg		;95f7   ; If negative, the sign is noted down
	inc b			;95f9
L_95FA:
	ld h,a			;95fa
	ld c,000h		;95fb
	ld a,(0e204h)		;95fd   ; And 0xE204: its row
	ld d,a			;9600
	ld a,(ix+004h)		;9601
	sub d			;9604
	jr nc,L_960A		;9605
	neg		;9607
	inc c			;9609
L_960A:
	ld l,a			;960a
	rra			;960b   ; The high nibble of one and the high nibble of the other
	rra			;960c   ; The high nibble of the distance in X
	rra			;960d   ; The four high bits
	rra			;960e
	and 00fh		;960f
	ld e,a			;9611
	ld a,h			;9612
	and 0f0h		;9613
	or e			;9615
	ld e,a			;9616
	ld d,000h		;9617
	sla e		;9619
	rl d		;961b
	push hl			;961d
	ld hl,09657h		;961e   ; The table at 0x9657, times two
	add hl,de			;9621
	ld e,(hl)			;9622
	inc hl			;9623
	ld d,(hl)			;9624
	bit 0,b		;9625   ; And the sign, with the two's complement
	call z,06729h		;9627
	ld (ix+019h),e		;962a   ; Bytes 25 and 26: the horizontal acceleration
	ld (ix+01ah),d		;962d
	pop hl			;9630
	ld a,h			;9631   ; Now the other way round: the nibbles crossed
	rra			;9632   ; The nibbles crossed
	rra			;9633   ; The high nibble of one and the low nibble of the other
	rra			;9634
	rra			;9635
	and 00fh		;9636
	ld e,a			;9638
	ld a,l			;9639
	and 0f0h		;963a
	or e			;963c
	ld e,a			;963d
	ld d,000h		;963e
	sla e		;9640
	rl d		;9642
	ld hl,09657h		;9644
	add hl,de			;9647
	ld e,(hl)			;9648
	inc hl			;9649
	ld d,(hl)			;964a
	bit 0,c		;964b
	call z,06729h		;964d
	ld (ix+017h),e		;9650   ; And bytes 23 and 24: the vertical one
	ld (ix+018h),d		;9653
	ret			;9656

