; ----------------------------------------------------------------------
; THE SHIP'S SPEED IS A REPEATED SUM
; The speed upgrade does not multiply: it takes the speed of one unit and
; ADDS it to itself as many times as the steps it has (0xE202, capped at
; seven) plus three. Eight speed steps, and not a single multiplication.
; ----------------------------------------------------------------------
times_speed_steps:		; Adds the two speeds to themselves 3 + (0xE202) times: that is the speed upgrade
	ld a,(0e202h)		;9b4d   ; 0xE202: the speed steps
	cp 008h		;9b50   ; Seven at most
	jp c,L_9B57		;9b52
	ld a,007h		;9b55
L_9B57:
	add a,003h		;9b57   ; Plus three: the starting speed
	ld h,a			;9b59
	ex af,af'			;9b5a
	ld a,h			;9b5b
	ld l,c			;9b5c
	ld h,b			;9b5d
L_9B5E:
	add hl,bc			;9b5e   ; The horizontal speed, added to itself
	dec a			;9b5f   ; The steps plus three
	jp nz,L_9B5E		;9b60
	ld c,l			;9b63
	ld b,h			;9b64
	ld l,e			;9b65
	ld h,d			;9b66
	ex af,af'			;9b67
L_9B68:
	add hl,de			;9b68   ; And the Y one
	dec a			;9b69   ; And the vertical one
	jp nz,L_9B68		;9b6a   ; The vertical one, already multiplied
	ld e,l			;9b6d
	ld d,h			;9b6e
	ret			;9b6f
end_game:		; Copies 0xE130 to 0xE06B and clears the flag at 0xE05F
