	ld (0e06bh),a		;9b73
	xor a			;9b76
	ld (0e05fh),a		;9b77
	ret			;9b7a
kill_ship:		; Leaves 0xFF in the ship and in its two options and sets the speed steps to zero
	ld hl,0e200h		;9b7b
	ld a,(hl)			;9b7e
	or a			;9b7f
	ret m			;9b80
	ld de,00020h		;9b81   ; Thirty-two bytes: the next card
	ld b,003h		;9b84   ; The ship and its two options
L_9B86:
	ld (hl),0ffh		;9b86
	add hl,de			;9b88
	djnz L_9B86		;9b89
	xor a			;9b8b
	ld (0e202h),a		;9b8c   ; 0xE202 to zero: the speed is lost
	jr set_up_ship_card		;9b8f
next_ship_state:		; Decrements the counter and, when it runs out, increments the state; past 4 the game is over
	ld hl,0e201h		;9b91
	dec (hl)			;9b94   ; 0xE201: the frames left in this state
	ret nz			;9b95
	inc l			;9b96
	inc (hl)			;9b97
	ld a,(hl)			;9b98
	cp 004h		;9b99   ; Four states
	jr nc,end_game		;9b9b
set_up_ship_card:		; Takes from the table at 0x9BD2 the frames the state lasts and the sprite card of the ship and of its two options
	ld hl,09bd2h		;9b9d   ; The table at 0x9BD2, indexed by the state
	call 047aeh		;9ba0
	ex de,hl			;9ba3
	ld a,(hl)			;9ba4
	ld (0e201h),a		;9ba5   ; The frames it lasts
	inc hl			;9ba8
	ld de,0e207h		;9ba9
	ldi		;9bac   ; The four bytes of the card
	ldi		;9bae
	ldi		;9bb0
	ldi		;9bb2
	ld de,0e224h		;9bb4   ; And the two options, 0xE224 and 0xE244
	call set_up_the_option		;9bb7
	ld de,0e244h		;9bba
set_up_the_option:		; The option goes on the ship's row and at its column plus the offset from the table
	ld a,(0e204h)		;9bbd   ; The ship's row
	ld (de),a			;9bc0
	inc e			;9bc1
	inc e			;9bc2
	ld a,(0e206h)		;9bc3   ; And its column plus the offset
	add a,(hl)			;9bc6
	ld (de),a			;9bc7
	ld a,006h		;9bc8   ; Six bytes further on, the pattern and the colour
	add a,e			;9bca
	ld e,a			;9bcb
	inc hl			;9bcc
	ldi		;9bcd
	ldi		;9bcf
	ret			;9bd1

