; ----------------------------------------------------------------------
; THE OPTION'S QUEUE IS FILLED USING THE STACK
; The options follow the ship with a delay: its last sixteen positions
; have to be kept. When they are created, that queue is filled in one go
; with the current position, and to do that the cartridge does something
; you do not see every day: it points the STACK POINTER at the queue
; (`ld sp,hl`), does eight `push bc` in a row (sixteen bytes in sixteen
; instructions) and restores SP, all with interrupts disabled so that
; nobody uses the stack in the meantime.
; ----------------------------------------------------------------------
set_up_one_option:		; Copies the ship's position into the option's card and fills its position queue with `push`
	ld a,(0e20bh)		;9bfb   ; 0xE20B: how many options there are
	dec a			;9bfe
	ld hl,0e204h		;9bff   ; With one, the position comes from the ship; with two, from the first option
	ld de,0e220h		;9c02
	jr z,L_9C0D		;9c05
	ld hl,0e224h		;9c07
	ld de,0e240h		;9c0a
L_9C0D:
	ld a,001h		;9c0d
	ld (de),a			;9c0f
	ld c,(hl)			;9c10   ; The X and the Y
	inc l			;9c11   ; The X and the Y
	inc l			;9c12   ; The Y
	ld b,(hl)			;9c13
	ld a,004h		;9c14
	add a,e			;9c16
	ld e,a			;9c17
	ld a,c			;9c18
	ld (de),a			;9c19
	inc e			;9c1a
	inc e			;9c1b
	ld a,b			;9c1c
	ld (de),a			;9c1d
	ld a,005h		;9c1e
	add a,e			;9c20
	ld e,a			;9c21
	ex de,hl			;9c22
	ld (hl),000h		;9c23   ; Pattern 0x44 and colour 0x0A
	inc l			;9c25   ; Pattern 0x44
	ld (hl),044h		;9c26
	inc l			;9c28
	ld (hl),00ah		;9c29
	ld a,013h		;9c2b
	add a,l			;9c2d
	ld l,a			;9c2e
	ld iy,00000h		;9c2f   ; The stack pointer is saved...
	add iy,sp		;9c33
	di			;9c35
	ld sp,hl			;9c36   ; ...pointed at the queue...
	ld a,008h		;9c37
L_9C39:
	push bc			;9c39   ; ...eight `push`: sixteen bytes in one go...
	dec a			;9c3a
	jr nz,L_9C39		;9c3b
	ld sp,iy		;9c3d   ; ...and restored
	ei			;9c3f
	ret			;9c40
run_options:		; Every two frames pushes the ship's position into the queue, and the options come out at the other end
	ld a,(0e1c0h)		;9c41   ; Not with the screen stopped
	and a			;9c44
	ret nz			;9c45
	ld a,(0e200h)		;9c46
	dec a			;9c49
	ret m			;9c4a
	ld a,(0e20bh)		;9c4b   ; Nor without options
	or a			;9c4e   ; Not without options
	ret z			;9c4f
	exx			;9c50
	ld b,a			;9c51
	exx			;9c52
	call animate_options		;9c53
	exx			;9c56
	ld a,(0e009h)		;9c57   ; With the joystick still or on an exact diagonal, the queue does not advance
	and 00fh		;9c5a   ; The four direction bits
	ret z			;9c5c   ; With the joystick still, the queue does not advance
	cp 003h		;9c5d
	ret z			;9c5f
	cp 00ch		;9c60
	ret z			;9c62
	cp 00fh		;9c63
	ret z			;9c65
	dec b			;9c66   ; With two options, both
	jr z,shift_one_queue		;9c67   ; Nor on an exact diagonal
	call shift_one_queue		;9c69
	ld hl,0e250h		;9c6c
	ld de,0e244h		;9c6f
	jr L_9C7A		;9c72
shift_one_queue:		; Pushes the new position in at the front and shifts the sixteen bytes of the queue
	ld hl,0e230h		;9c74
	ld de,0e224h		;9c77
L_9C7A:
	push hl			;9c7a   ; The new position, at the front
	ldi		;9c7b
	inc e			;9c7d
	ldi		;9c7e
	pop de			;9c80
	ld bc,0000eh		;9c81   ; Fourteen bytes: the rest of the queue
	ldir		;9c84
	ld a,l			;9c86   ; And the one from sixteen frames ago, at the end
	sub 03ch		;9c87   ; 0x3C bytes back
	ld l,a			;9c89
	ldi		;9c8a
	inc l			;9c8c
	ldi		;9c8d
	ret			;9c8f
animate_options:		; Every two frames advances the options' drawing, four round and round, from the table at 0x9CBA
	ld b,a			;9c90
	ld hl,0e182h		;9c91   ; 0xE182: one in every two frames
	inc (hl)			;9c94
	ld a,(hl)			;9c95
	cp 002h		;9c96
	ret c			;9c98
	ld (hl),000h		;9c99
	inc l			;9c9b
	inc (hl)			;9c9c   ; 0xE183: which drawing they are on
	dec b			;9c9d   ; With two options, both
	jr z,L_9CA6		;9c9e
	ld de,0e24ch		;9ca0
	call L_9CA9		;9ca3
L_9CA6:
	ld de,0e22ch		;9ca6
L_9CA9:
	ld hl,09cbah		;9ca9
	ld a,(0e183h)		;9cac
	and 003h		;9caf   ; Four drawings round and round
	add a,a			;9cb1
	call 0405dh		;9cb2
	ldi		;9cb5
	ldi		;9cb7
	ret			;9cb9

; ----------------------------------------------------------------------
; DATA option_drawings: Four (pattern, colour) pairs the option blinks with.
