;   0x9cba..0x9cc2  (8 bytes)
DATA_option_drawings:
	defb 044h,00ah	; 9cba
	defb 044h,009h	; 9cbc
	defb 048h,008h	; 9cbe
	defb 048h,006h	; 9cc0

