	or a			;9d0c
	call nz,L_9D26		;9d0d
	ld a,(ix+00dh)		;9d10   ; 13: the double
	or a			;9d13
	call nz,fire_double		;9d14
	ld a,(ix+00eh)		;9d17   ; 14: the laser
	or a			;9d1a
	call nz,fire_laser		;9d1b
	ld a,(ix+00fh)		;9d1e   ; And 15: the missile
